  public void LayoutSmokeTest(string directory){Directory.CreateDirectory(directory);var errors=new List<string>();for(int stage=0;stage<3;stage++){page=stage;Render();foreach(var size in new[]{new Size(1120,740),new Size(800,620)}){Size=size;for(int n=0;n<4;n++){LayoutShell();Application.DoEvents();}CheckOverlap(shell,errors);CheckWidths(shell,errors);if(viewport.HorizontalScroll.Visible)errors.Add("Horizontal scrollbar "+size+" page "+stage);using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(Path.Combine(directory,"page-"+stage+"-"+size.Width+".png"));}}}CheckStartupAndLink(errors);File.WriteAllText(Path.Combine(directory,"layout-result.json"),json.Serialize(new{errors=errors}));Environment.ExitCode=errors.Count==0?0:1;exit=true;Close();}
