  void CheckWidths(Control parent,List<string> errors){foreach(Control c in parent.Controls){if(!c.Visible)continue;if(c.Right>parent.ClientSize.Width-parent.Padding.Right+1)errors.Add("Width overflow: "+c.GetType().Name+" in "+parent.GetType().Name);if(c is Panel)CheckWidths(c,errors);}}
