  void Sync(){if(email!=null){string address=email.Text.Trim().ToLowerInvariant();if(S("address")!=address)mailOK=false;cfg["address"]=address;}if(password!=null){string pass=password.Text.Replace(" ","").Trim();if(S("app_password")!=pass)mailOK=false;cfg["app_password"]=pass;}if(api!=null){if(S("api_key")!=api.Text.Trim())aiOK=false;cfg["api_key"]=api.Text.Trim();}if(startup!=null){cfg["startup"]=startup.Checked;cfg["shortcut"]=shortcut.Checked;}badge.Text=S("activation_mode")=="sender"?"ללא קוד":S("trigger_code");}
  void Save(){var encrypted=ProtectedData.Protect(Encoding.UTF8.GetBytes(json.Serialize(cfg)),null,DataProtectionScope.CurrentUser);string temp=Path.Combine(data,"settings.tmp"),path=Path.Combine(data,"settings.dat");File.WriteAllBytes(temp,encrypted);if(File.Exists(path))File.Delete(path);File.Move(temp,path);}
  void LoadSettings(){try{string path=Path.Combine(data,"settings.dat");if(!File.Exists(path))return;var raw=ProtectedData.Unprotect(File.ReadAllBytes(path),null,DataProtectionScope.CurrentUser);foreach(var pair in json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(raw)))cfg[pair.Key]=pair.Value;}catch{MessageBox.Show("לא ניתן לפתוח את ההגדרות הקודמות. אפשר להתחבר מחדש.","MailAI");}}
  string ValidateMail(){if(S("activation_mode")=="sender"&&!Regex.IsMatch(S("allowed_sender"),@"^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$"))return "כתובת השולח המורשה אינה תקינה.";if(!Regex.IsMatch(S("address"),@"^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$"))return "יש להזין כתובת מייל תקינה.";if(!Regex.IsMatch(S("app_password"),"^[A-Za-z0-9]{16}$"))return "יש להזין סיסמת אפליקציה בת 16 תווים, ולא את סיסמת החשבון.";if(S("activation_mode")!="sender"&&!Regex.IsMatch(S("trigger_code"),"^[0-9]{4}$"))return "הקוד צריך להכיל ארבע ספרות באנגלית.";return null;}
  void Busy(bool on,string message){if(IsDisposed||Disposing)return;busy=on;next.Enabled=back.Enabled=body.Enabled=!on;UseWaitCursor=on;status.ForeColor=Muted;status.Text=message;}
  async Task<bool> Check(string flag){Save();return await Task.Run(()=>{var info=new ProcessStartInfo(Path.Combine(app,"python","python.exe"),"\""+Path.Combine(app,"mailai.py")+"\" "+flag){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=app};using(var p=Process.Start(info)){checkProcess=p;var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(flag=="--wait-login"?620000:110000)){p.Kill();p.WaitForExit();return false;}Task.WaitAll(stdout,stderr);checkProcess=null;return p.ExitCode==0&&stdout.Result.Contains(flag=="--check-mail"?"MAIL_OK":"AI_OK");}});}
  async Task Next(){if(busy||Running())return;Sync();string error=ValidateMail();if(error!=null){status.Text=error;return;}try{if(page==0){Busy(true,"בודק חיבור ל-Gmail. הבדיקה אינה שולחת הודעות...");mailOK=await Check("--check-mail");if(mailOK){page=1;Render();if(S("backend")=="browser"){status.Text="עכשיו נשאר להתחבר עם המייל והסיסמה של מייל הבוט בחלון הבא.";await Task.Delay(3500);await ConnectBrowser();}}else status.Text="חיבור המייל לא הצליח. בדוק כתובת, סיסמת אפליקציה וחיבור לאינטרנט.";}else if(page==1){if(S("backend")=="api"&&S("api_key").Length<20){status.Text="יש להזין מפתח Gemini API תקין.";return;}Busy(true,"בודק חיבור לבינה המלאכותית...");aiOK=await Check(S("backend")=="api"?"--check-ai":"--wait-login");if(aiOK){page=2;Render();}else status.Text=S("backend")=="api"?"חיבור ה-API לא אושר. בדוק את המפתח והמכסות.":"החיבור לא אושר. התחבר ל-Gemini, סגור את החלון ונסה שוב.";}else await Launch();}catch{status.Text="הבדיקה לא הושלמה. בדוק את החיבור ונסה שוב.";}finally{Busy(false,status.Text);next.Enabled=!Running();}}
  async Task Launch(){if(Running())return;Sync();string error=ValidateMail();if(error!=null){status.Text=error;return;}try{Busy(true,"בודק חיבורים לפני ההפעלה...");if(!mailOK)mailOK=await Check("--check-mail");if(!mailOK){status.Text="נדרש חיבור מחדש למייל.";if(!automaticStartup)tray.ShowBalloonTip(4000,"MailAI",status.Text,ToolTipIcon.Warning);return;}if(!aiOK)aiOK=await Check("--check-ai");if(!aiOK){status.Text="נדרשת התחברות מחדש ל-Gemini.";if(!automaticStartup)tray.ShowBalloonTip(4000,"MailAI",status.Text,ToolTipIcon.Warning);return;}Save();if(staging){if(!mailOK||!aiOK)throw new InvalidOperationException();Environment.ExitCode=42;exit=true;Close();return;}Options();string path=Path.Combine(data,"STOP");if(File.Exists(path))File.Delete(path);launched=DateTime.UtcNow;worker=Process.Start(new ProcessStartInfo(Path.Combine(app,"python","pythonw.exe"),"\""+Path.Combine(app,"mailai.py")+"\" --run"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=app});page=2;Render();status.Text="הבוט מתחבר ובודק הודעות חדשות...";}catch{status.Text="ההפעלה לא הושלמה. נסה להתחבר מחדש.";}finally{Busy(false,status.Text);next.Enabled=!Running();stop.Visible=Running();}}
  bool Running(){try{return worker!=null&&!worker.HasExited;}catch{return false;}}
  void RefreshStatus(){if(busy)return;if(Running()){string p=Path.Combine(data,"status.json");if(File.Exists(p)&&File.GetLastWriteTimeUtc(p)>=launched&&DateTime.UtcNow-File.GetLastWriteTimeUtc(p)<TimeSpan.FromSeconds(65)){status.ForeColor=Mint;status.Text="●  הבוט פעיל ובודק הודעות חדשות. אפשר למזער ולהמשיך לעבוד.";}stop.Visible=true;next.Enabled=false;}else if(worker!=null){status.Text="הבוט נעצר. אפשר לבדוק חיבורים ולהריץ שוב.";next.Enabled=true;next.Text="התקן והפעל  ✦";stop.Visible=false;worker.Dispose();worker=null;mailOK=aiOK=false;}}
  async Task Stop(){automaticStartup=false;bootRetry.Stop();if(!Running())return;status.Text="עוצר את הבוט...";File.WriteAllText(Path.Combine(data,"STOP"),"stop");var child=worker;await Task.Run(()=>{try{if(!child.WaitForExit(10000)){using(var killer=Process.Start(new ProcessStartInfo("taskkill.exe","/PID "+child.Id+" /T /F"){UseShellExecute=false,CreateNoWindow=true})){killer.WaitForExit(5000);}if(!child.HasExited)child.Kill();child.WaitForExit();}}catch{}});RefreshStatus();}
  void Options(){using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(B("startup"))key.SetValue("MailAI","\""+Application.ExecutablePath+"\" --background");else key.DeleteValue("MailAI",false);}string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"MailAI.lnk");if(B("shortcut")){var type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type);object link=type.InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{path});var t=link.GetType();t.InvokeMember("TargetPath",System.Reflection.BindingFlags.SetProperty,null,link,new object[]{Application.ExecutablePath});t.InvokeMember("WorkingDirectory",System.Reflection.BindingFlags.SetProperty,null,link,new object[]{app});t.InvokeMember("Save",System.Reflection.BindingFlags.InvokeMethod,null,link,null);}else if(File.Exists(path))File.Delete(path);}
  async Task ConnectBrowser(){try{Busy(true,"מחכה להתחברות שלך בחלון Google...");aiOK=await Check("--wait-login");if(aiOK){page=2;Render();status.Text="החיבור זוהה בהצלחה. אפשר להתקין ולהפעיל.";}else status.Text="החיבור לא הושלם. אפשר לפתוח שוב את חלון ההתחברות.";}catch{status.Text="לא ניתן להשלים את החיבור. בדוק ש-Chrome מותקן ונסה שוב.";}finally{Busy(false,status.Text);}}
  void OpenWindow(){Show();WindowState=FormWindowState.Normal;Activate();}
 }
